<?php require_once '../conexao.php';require_once '../includes/rbac.php';exigirCargo(['diretor']);$de=$_GET['de']??date('Y-m-01');$ate=$_GET['ate']??date('Y-m-t');$s=$pdo->prepare("SELECT a.*,p.nome profissional,TIMESTAMPDIFF(YEAR,a.nascimento,CURDATE()) idade FROM agendamentos a JOIN profissionais p ON p.id=a.profissional_id WHERE a.data BETWEEN ? AND ? ORDER BY a.data,a.horario");$s->execute([$de,$ate]);$rows=$s->fetchAll();if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename=consultas-aura.csv');echo "\xEF\xBB\xBF";$o=fopen('php://output','w');fputcsv($o,['Data','Hora','Paciente','Idade','Telefone','Serviço','Profissional','Status'],';');foreach($rows as $r)fputcsv($o,[$r['data'],substr($r['horario'],0,5),$r['nome'],$r['idade'],$r['telefone'],$r['servico'],$r['profissional'],$r['status']],';');fclose($o);exit;}?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Relatórios | Aura</title><link rel="stylesheet" href="../css/style.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="side-logo" href="index.php"><img src="../img/logo-aura-oficial.png"></a><small>DIRETORIA</small><a href="index.php">Dashboard</a><a href="usuarios.php">Usuários e acessos</a><a href="funcionarios.php">Dados dos funcionários</a><a class="active" href="relatorios.php">Consultas / planilha</a><a href="../logout.php">Sair</a></aside><main class="dashboard"><div class="dash-head"><div><p class="eyebrow">RELATÓRIOS</p><h1>Consultas</h1></div></div><form class="filter-bar"><label>De<input type="date" name="de" value="<?=$de?>"></label><label>Até<input type="date" name="ate" value="<?=$ate?>"></label><button class="btn">Filtrar</button><a class="btn btn-outline" href="?de=<?=$de?>&ate=<?=$ate?>&export=csv">Exportar CSV</a></form><div class="table-wrapper"><table><thead><tr><th>Data</th><th>Hora</th><th>Paciente</th><th>Idade</th><th>Telefone</th><th>Serviço</th><th>Profissional</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d/m/Y',strtotime($r['data']))?></td><td><?=substr($r['horario'],0,5)?></td><td><?=htmlspecialchars($r['nome'])?></td><td><?=$r['idade']?></td><td><?=htmlspecialchars($r['telefone'])?></td><td><?=htmlspecialchars($r['servico'])?></td><td><?=htmlspecialchars($r['profissional'])?></td><td><?=$r['status']?></td></tr><?php endforeach;?></tbody></table></div></main></div></body></html>
